@ Horn-Horn-Duncan formula @

n <- nrow(y)
k <- ncol(x)
a <- n/(n-k)
sig2 <- (t(e) %*% e)/(n-k)
u1 <- x*(e%*%matrix(1,1,k))
u2 <- x*((e/(1-leverage))%*%matrix(1,1,k))
u3 <- x*((e/sqrt(1-leverage))%*%matrix(1,1,k))
v0 <- xx*sig2
xx <- solve(t(x)%*%x)
v1 <- xx %*% (t(u1)%*%u1) %*% xx
v1a <- a * xx %*% (t(u1)%*%u1) %*% xx
v2 <- xx %*% (t(u2)%*%u2) %*% xx
v3 <- xx %*% (t(u3)%*%u3) %*% xx
s0 <- sqrt(diag(v0))
# Homoskedastic formula
s1 <- sqrt(diag(v1))
# White formula
s1a <- sqrt(diag(v1a))
# Scaled White formula
s2 <- sqrt(diag(v2))
# Andrews formula
s3 <- sqrt(diag(v3))
# Horn-Horn-Duncan formula
